function LadderStruggleFormationTeamCell:CleanProperties()
    self.data = nil
    self.cellIndex = nil
    self.teamInfo = nil
    self.canFormation = nil
    self.systemName = nil
    self.component = nil
end

function LadderStruggleFormationTeamCell:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
