function LadderStruggleFormationTeamCell:InitComponent()
    if isNull(self.LB_MembersNode.Env) then
        self.LB_MembersNode:Init()
    end
end

function LadderStruggleFormationTeamCell:UpdateTeamInfo(teamInfo)
    if IsNull(teamInfo) then return end

    self.teamInfo = teamInfo
    local cardsInfo = teamInfo.cardsInfo
    self.LB_MembersNode.Env:Refresh(cardsInfo, true, 0.5, function()
        if self.canFormation then
            -- print("[异步PVP] 编队", self.component.questId, self.cellIndex)
            UIModule.OpenDialog(
                {id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self.component.questId, teamIndex = self.cellIndex }}
            )
        end
    end, false, nil, not self.canFormation, self.component.questId, true)

    -- 设置队伍战力
    self.Txt_CombatValue.text = tostring(teamInfo.combatValue)
end

function LadderStruggleFormationTeamCell:SetParameters(index, canFormation)
    self.cellIndex = index
    self.canFormation = canFormation
end

